create table public.student_fee_charges(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,student_id uuid not null references public.students(id) on delete cascade,academic_year_id uuid not null references public.academic_years(id),fee_structure_id uuid references public.fee_structures(id),description text not null,charge_date date not null default current_date,due_date date not null,amount numeric(12,2) not null check(amount>=0),discount_amount numeric(12,2) not null default 0 check(discount_amount>=0),status text not null default 'open' check(status in('open','paid','waived','cancelled')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),check(discount_amount<=amount));
create table public.fee_payment_allocations(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,payment_id uuid not null references public.fee_payments(id) on delete cascade,charge_id uuid not null references public.student_fee_charges(id) on delete cascade,amount numeric(12,2) not null check(amount>0),created_at timestamptz not null default now(),unique(payment_id,charge_id));
create table public.fee_adjustments(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,student_id uuid not null references public.students(id),charge_id uuid references public.student_fee_charges(id),adjustment_type text not null check(adjustment_type in('discount','waiver','refund','credit','debit')),amount numeric(12,2) not null check(amount>0),reason text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create index student_fee_charges_due_idx on public.student_fee_charges(school_id,due_date,status);create index student_fee_charges_student_idx on public.student_fee_charges(student_id,academic_year_id);create index fee_alloc_charge_idx on public.fee_payment_allocations(charge_id);create index fee_alloc_payment_idx on public.fee_payment_allocations(payment_id);
alter table public.student_fee_charges enable row level security;alter table public.fee_payment_allocations enable row level security;alter table public.fee_adjustments enable row level security;
create policy "read charges" on public.student_fee_charges for select to authenticated using(public.is_school_member(school_id) or public.can_view_student(student_id));create policy "manage charges" on public.student_fee_charges for all to authenticated using(public.can_manage_finance(school_id)) with check(public.can_manage_finance(school_id));
create policy "read allocations" on public.fee_payment_allocations for select to authenticated using(public.is_school_member(school_id));create policy "manage allocations" on public.fee_payment_allocations for all to authenticated using(public.can_manage_finance(school_id)) with check(public.can_manage_finance(school_id));
create policy "read adjustments" on public.fee_adjustments for select to authenticated using(public.is_school_member(school_id) or public.can_view_student(student_id));create policy "manage adjustments" on public.fee_adjustments for all to authenticated using(public.can_manage_finance(school_id)) with check(public.can_manage_finance(school_id));